// As proposed: the public surface hides its coupling and error handling
interface CheckoutFeature {
    fun start(activity: Activity, orderId: String)   // UI owns the lifecycle
    suspend fun confirm(): Boolean                   // Boolean swallows the failure
}

// What the review asks for: typed state and events crossing a real boundary
sealed interface CheckoutState {
    data object Idle : CheckoutState
    data object Confirming : CheckoutState
    data class Confirmed(val orderId: String) : CheckoutState
    data class Failed(val reason: String, val retryable: Boolean) : CheckoutState
}

interface CheckoutFeature {
    fun observeState(): Flow<CheckoutState>
    suspend fun confirm(orderId: String): Unit       // failures become state, not null
}

interface SyncEngine {
    fun observeStatus(): Flow<SyncStatus>
    suspend fun sync(): Outcome<SyncResult>
}

class LegacySyncEngine(
    private val transport: LegacyTransport,
) : SyncEngine {
    override fun observeStatus(): Flow<SyncStatus> = transport.observeQueue()
    override suspend fun sync(): Outcome<SyncResult> = transport.pushPending()
}

class NewSyncEngine(
    private val queue: SyncQueueDao,
    private val api: SyncApi,
) : SyncEngine {
    override fun observeStatus(): Flow<SyncStatus> = queue.observePending()
    override suspend fun sync(): Outcome<SyncResult> =
        api.pushAll(queue.drain()).also { queue.retainFailed() }
}

// The seam: one factory, a flag deciding the cohort's engine
class SyncEngineFactory(
    private val flags: FeatureFlagProvider,
    private val legacy: LegacySyncEngine,
    private val fresh: NewSyncEngine,
) {
    fun engineFor(): SyncEngine =
        if (flags.isEnabled(FeatureFlag.NEW_SYNC)) fresh else legacy
}

class MessageSync(
    private val legacy: LegacyMessageStore,
    private val dao: MessageDao,
) {
    suspend fun write(message: Message) {
        dao.upsert(message.toEntity())      // new source of truth
        legacy.append(message.toWire())     // dual-write until cutover
    }

    // Reconciliation: drift must reach zero before the legacy path is deleted
    suspend fun verify(scope: String): Long {
        val expected = legacy.count(scope)
        val actual = dao.countForScope(scope)
        return expected - actual            // logged; alerted when non-zero
    }
}

